const STOPWORDS = new Set(['and', 'the', 'is', 'in', 'to', 'through', 'using', 'of', 'for', 'a']);
const tokenizedDocs = inputs.documents.map((doc, docId) => {
  const words = doc
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOPWORDS.has(w));
  return { docId, words };
});
return { tokenizedDocs };
```

--- Cell ID: 8becdfd3-41bd-4ef6-977d-40e71209088e ---
```javascript
const docCount = inputs.tokenizedDocs.length;
const docFreq = {};
const termFreqs = [];

for (const d of inputs.tokenizedDocs) {
  const tf = {};
  const seenInDoc = new Set();
  for (const w of d.words) {
    tf[w] = (tf[w] || 0) + 1;
    seenInDoc.add(w);
  }
  termFreqs.push({ docId: d.docId, tf, wordCount: d.words.length });
  for (const w of seenInDoc) {
    docFreq[w] = (docFreq[w] || 0) + 1;
  }
}

return { docCount, docFreq, termFreqs };
```

